{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.workflow.model.service.WorkflowManager;
import org.joget.commons.util.LogUtil;

// Get services
DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");

// Inputs
String token = "#form.account_reset.token#";
String plainPassword = "#form.account_reset.retypePassword#"; // Assuming plain password is submitted

Connection con = null;
PreparedStatement selectStmt = null;
PreparedStatement updateStmt = null;
ResultSet rs = null;

try {
 con = ds.getConnection();

 // Step 1: Get user ID by token -> email
 String recordId = null;
 selectStmt = con.prepareStatement(
 "SELECT du.id " +
 "FROM dir_user du " +
 "JOIN app_fd_account_forgot af ON af.c_email = du.email " +
 "WHERE af.c_token = ? " +
 "ORDER BY af.dateCreated DESC LIMIT 1"
 );
 selectStmt.setString(1, token);
 rs = selectStmt.executeQuery();

 if (rs.next()) {
 recordId = rs.getString("id");
 // System.out.println("Found user ID to reset: " + recordId);
 LogUtil.info("########. Found user ID to reset: ###########", recordId);
 } else {
 throw new Exception("No user found for the provided token.");
 }

 // Step 2: Update password using SQL MD5
 updateStmt = con.prepareStatement("UPDATE dir_user SET password = MD5(?) WHERE id = ?");
 updateStmt.setString(1, plainPassword);
 updateStmt.setString(2, recordId);

 int rows = updateStmt.executeUpdate();
 // System.out.println("Rows affected: " + rows);
 LogUtil.info("########. Rows affected: ###########", rows + "");

 if (rows == 0) {
 throw new Exception("Password update failed for user ID: " + recordId);
 }

 // Save to workflow variable if declared
 wm.activityVariable(workflowAssignment.getActivityId(), "reset_user_id", recordId);

} catch (Exception e) {
 // System.out.println("ERROR in BeanShell: " + e.getMessage());
 LogUtil.info("########. ERROR in BeanShell: ###########", e.getMessage());
 e.printStackTrace();
 throw new RuntimeException("Failed to reset password: " + e.getMessage(), e);
} finally {
 if (rs != null) try { rs.close(); } catch (Exception e) {}
 if (selectStmt != null) try { selectStmt.close(); } catch (Exception e) {}
 if (updateStmt != null) try { updateStmt.close(); } catch (Exception e) {}
 if (con != null) try { con.close(); } catch (Exception e) {}
}
"}}]}

{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.sql.*;
import javax.sql.DataSource;
import org.joget.apps.app.service.AppUtil;
import org.joget.workflow.model.service.WorkflowManager;
import org.joget.commons.util.LogUtil;

// ===== Configuration =====
String processId = workflowAssignment.getProcessId();
String username = "#form.account_signup.email#";
String departmentId = "#form.account_signup.departmentId#";
String organizationId = "#form.account_signup.organizationId#";
int maxRetries = 5;
int waitMs = 500; // milliseconds between retries

// get workflowManager bean
WorkflowManager wm = (WorkflowManager) AppUtil.getApplicationContext().getBean("workflowManager");


String logPrefix = "ScriptTask";
LogUtil.info(logPrefix, "Script started for user: " + username);

// ===== Get Joget datasource via Spring bean =====
Object obj = AppUtil.getApplicationContext().getBean("setupDataSource");
DataSource ds = (DataSource) obj;

try {
 // ===== Only continue if departmentId is provided =====
 if (departmentId == null || departmentId.trim().isEmpty()) {
 LogUtil.info(logPrefix, "DepartmentId is empty, skipping dir_employment insert.");
 // set a process variable via workflowAssignment
 // Variable setzen
		wm.processVariable(workflowAssignment.getProcessId(), "scriptErrorMessage", "DepartmentId is empty, employment record not created.");
 return;
 }

 boolean userExists = false;
 Connection con = null;
 PreparedStatement ps = null;
 ResultSet rs = null;

 // ===== Retry loop to wait until user exists =====
 for (int i = 0; i < maxRetries; i++) {
 try {
 con = ds.getConnection();
 ps = con.prepareStatement("SELECT id FROM dir_user WHERE username = ?");
 ps.setString(1, username);
 rs = ps.executeQuery();

 if (rs.next()) {
 userExists = true;
 LogUtil.info(logPrefix, "User found with id: " + rs.getString("id"));
 break;
 } else {
 LogUtil.info(logPrefix, "User not found yet, retry " + (i+1) + "/" + maxRetries);
 Thread.sleep(waitMs);
 }
 } finally {
 if (rs != null) { rs.close(); rs = null; }
 if (ps != null) { ps.close(); ps = null; }
 if (con != null) { con.close(); con = null; }
 }
 }

 if (!userExists) {
 String msg = "User '" + username + "' not found in dir_user after " + maxRetries + " retries.";
 LogUtil.error(logPrefix, msg);
 workflowManager.setVariable(processId, "scriptErrorMessage", msg);
 throw new RuntimeException(msg);
 }

 // ===== Insert into dir_employment =====
 con = ds.getConnection();
 ps = con.prepareStatement(
 "INSERT INTO dir_employment (id, userId, departmentId, organizationId) " +
 "SELECT UUID(), id, ?, ? FROM dir_user WHERE username = ?"
 );
 ps.setString(1, departmentId);
 ps.setString(2, organizationId);
 ps.setString(3, username);

 int inserted = ps.executeUpdate();
 LogUtil.info(logPrefix, "dir_employment insert completed, rows inserted: " + inserted);

} catch (Exception e) {
 LogUtil.error(logPrefix, "Error in Script Task: " + e.getMessage(), e);
 workflowManager.setVariable(processId, "scriptErrorMessage", "Error: " + e.getMessage());
 throw new RuntimeException(e);
} finally {
 // close resources
}
"}}]}

