{"bcc":"","runInMultiThread":"","subject":"A new user has signed up and needs your approval","formDefId":"","toParticipantId":"Approver","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.util.Collection;
import java.util.Map;
import javax.servlet.http.HttpServletRequest;
import org.joget.apps.app.model.AppDefinition;
import org.joget.apps.app.service.AppPluginUtil;
