import org.joget.plugin.property.model.PropertyEditable;
import org.joget.workflow.model.WorkflowAssignment;
import org.joget.commons.util.LogUtil;


public Object sendMailToApprover(WorkflowAssignment wa, PluginManager pm, AppDefinition appDef, HttpServletRequest request) {
    try {
        LogUtil.info("BulkEmail", "Starting bulk email sending...");

        // Get directory manager and users from group
        ExtDirectoryManager directoryManager = 
            (ExtDirectoryManager) AppUtil.getApplicationContext().getBean("directoryManager");

        String groupId = "app_accountCreation_Approver";

        LogUtil.info("BulkEmail", "Looking up users in group " + groupId);

        Collection userList = directoryManager.getUsers(
            null,    // username
            null,    // name
            null,    // departmentId
            null,    // gradeId
            groupId, // groupId
            null,    // roleId
            null,    // active
            "firstName", // sort
            false,   // desc
            null,    // start
            null     // rows
        );

        if (userList == null || userList.isEmpty()) {
            LogUtil.info("BulkEmail", "No users found for group " + groupId);
            return null;
        }

        // Get Email Tool plugin
        Plugin plugin = pm.getPlugin("org.joget.apps.app.lib.EmailTool");

        if (plugin == null) {
            LogUtil.error("BulkEmail", null, "EmailTool plugin not found");
            return null;
        }

        // Get default properties (SMTP etc.)
        Map propertiesMap = AppPluginUtil.getDefaultProperties(plugin, null, appDef, wa);

        // Put injected objects into properties
        propertiesMap.put("pluginManager", pm);
        propertiesMap.put("appDef", appDef);
        propertiesMap.put("request", request);

        ApplicationPlugin emailTool = (ApplicationPlugin) plugin;

        String subject = "A new user has signed up and needs your approval";


      	String message = ""
    		+ "Hi Admin,<br><br>"
    		+ "A new user <strong>#form.account_signup.firstName# #form.account_signup.lastName#</strong> "
    		+ "(<em>#form.account_signup.email#</em>) has registered and is awaiting your approval.<br><br>"
    		+ "You can review and take action by clicking the link below:<br>"
    		+ "<a href='#envVariable.URL#'>Review Request</a><br><br>"
    		+ "Thank you,<br>"
    		+ "MOI Team";

        // Send to each user
        for (Object o : userList) {
            User user = (User) o;
            String email = user.getEmail();

            if (email != null && email.trim().length() > 0) {
                String trimmedEmail = email.trim();
                LogUtil.info("BulkEmail", "Sending email to: " + trimmedEmail);

                propertiesMap.put("toSpecific", trimmedEmail);
                propertiesMap.put("subject", subject);
                propertiesMap.put("message", message);

                if (emailTool instanceof PropertyEditable) {
                    ((PropertyEditable) emailTool).setProperties(propertiesMap);
                }

                emailTool.execute(propertiesMap);
            } else {
                LogUtil.info("BulkEmail", "User " + user.getUsername() + " has no email, skipping.");
            }
        }

        LogUtil.info("BulkEmail", "Bulk email completed successfully.");

    } catch (Exception e) {
        LogUtil.error("BulkEmail", e, "Error while sending bulk email");
    }

    return null;
}

// Call our method with injected variables
return sendMailToApprover(workflowAssignment, pluginManager, appDef, request);"}}],"p12":"","security":"TLS","password":"","storepass":"","isHtml":"","host":"","alias":"","from":"","cc":"tw@wiemann-business-consulting.com, packmutangana@gmail.com, afleser@arxia.com","toSpecific":"afleser@arxia.com","icsAttachement":"","retryCount":"","message":"Hi admin<br /><br />

