{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.util.Date;
import java.text.SimpleDateFormat;
import org.joget.workflow.model.service.WorkflowManager;
import org.joget.apps.app.service.AppService;
import org.joget.apps.app.service.AppUtil;
import java.sql.Connection;
import javax.sql.DataSource;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Timestamp;
import org.joget.commons.util.LogUtil;

WorkflowManager wm = (WorkflowManager) pluginManager.getBean("workflowManager");
AppService appService = (AppService) AppUtil.getApplicationContext().getBean("appService");
DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");

String token = "#form.account_reset.token#";
Connection con = null;
PreparedStatement stmt = null;
ResultSet rs = null;

try {
 con = ds.getConnection();

 if (!con.isClosed()) {
 stmt = con.prepareStatement(
 "SELECT c_email, c_token, c_isUsed, dateCreated " +
 "FROM app_fd_account_forgot WHERE c_token = ? " +
 "ORDER BY dateCreated DESC LIMIT 1"
 );
 stmt.setString(1, token);
 rs = stmt.executeQuery();

 if (rs.next()) {
 String cIsUsed = rs.getString("c_isUsed");
 Timestamp dateCreated = rs.getTimestamp("dateCreated");

 LogUtil.info("#########. Token check ###########", "Token: " + token + ", isUsed: " + cIsUsed + ", dateCreated: " + dateCreated);

 // Calculate if more than 3 minutes old
 long currentTime = System.currentTimeMillis();
 long recordTime = dateCreated.getTime();
 long timeDifferenceMillis = currentTime - recordTime;
 long threeMinutesMillis = 30 * 60 * 1000;

 boolean isExpired = timeDifferenceMillis > threeMinutesMillis;

 wm.activityVariable(workflowAssignment.getActivityId(), "isTokenUsed", cIsUsed);
 wm.activityVariable(workflowAssignment.getActivityId(), "isTokenExpired", String.valueOf(isExpired));

 LogUtil.info("#########. Expiry check ###########", "Expired: " + isExpired);
 } else {
 LogUtil.info("#########. Token not found ###########", token);
 wm.activityVariable(workflowAssignment.getActivityId(), "isTokenUsed", "true"); // Assume used
 wm.activityVariable(workflowAssignment.getActivityId(), "isTokenExpired", "true");
 }
 }

} catch (Exception e) {
 LogUtil.error("TokenValidationScript", e, "Error checking token expiration or usage");
 throw new RuntimeException("Token validation failed.");
} finally {
 if (rs != null) try { rs.close(); } catch (Exception e) {}
 if (stmt != null) try { stmt.close(); } catch (Exception e) {}
 if (con != null) try { con.close(); } catch (Exception e) {}
}
















