{"runInMultiThread":"","comment":"","tools":[{"className":"org.joget.apps.app.lib.BeanShellTool","properties":{"script":"import java.security.SecureRandom;
import org.joget.apps.app.service.AppUtil;
import org.joget.workflow.model.service.WorkflowManager;
final String TOKEN = "token";
final String ACTIVE = "active";
final int BYTES = 24;

String generateToken(int nBytes) {
 SecureRandom sr = new SecureRandom();
 byte[] buf = new byte[nBytes];
 sr.nextBytes(buf);
 try {
 return java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(buf);
 } catch (Throwable t) {
 StringBuilder sb = new StringBuilder(buf.length * 2);
 final char[] HEX = "0123456789abcdef".toCharArray();
 for (byte b : buf) {
 sb.append(HEX[(b >> 4) & 0xF]).append(HEX[b & 0xF]);
 }
 return sb.toString();
 }
}

String token = generateToken(BYTES);
WorkflowManager wm = (WorkflowManager) AppUtil.getApplicationContext().getBean("workflowManager");
wm.activityVariable(workflowAssignment.getActivityId(), TOKEN, token);
wm.activityVariable(workflowAssignment.getActivityId(), ACTIVE, "true");

"}}]}

{"script":"import org.joget.workflow.model.DecisionResult;
import org.joget.commons.util.LogUtil;
import org.joget.workflow.model.service.*;


//Transition Name to go to
String groupsRequested = "#form.account_signup.groupsRequested#";
int groupsRequestedArraySize;
String[] groupsRequestedArray = groupsRequested.split(";");

if (groupsRequested != "") {
 groupsRequestedArraySize = groupsRequestedArray.length;
} else {
 groupsRequestedArraySize = 0;
}

int groupCounter = Integer.valueOf("#variable.groupCounter#");


//LogUtil.info("Value of groupCounter : ", "" + groupCounter);
//LogUtil.info("Value of groupsRequested : ", groupsRequested);
//LogUtil.info("Value of groupsRequestedArray : ", Arrays.toString(groupsRequestedArray));
//LogUtil.info("Value of groupsRequestedArraySize : ", "" + groupsRequestedArraySize);


DecisionResult result = new DecisionResult();

/* Bean Shell Decision supports hash variable, and has access to the process instance context. */
